import {sampleTrialReplay,replayDuration} from './trial-replay.js';
// Export sampled positions from the same replay model used by 2D/3D. The portable
// player does not run an independent tactical simulation.
export function portableReplay(record){
 const duration=replayDuration(record.history),fps=20,frames=[];
 for(let i=0;i<=Math.ceil(duration*fps);i++){
  const s=sampleTrialReplay(record.history,Math.min(duration,i/fps)).frame;
  const round=p=>[+p.x.toFixed(2),+p.y.toFixed(2)];
  frames.push({players:Object.entries({...s.own,...s.opponents}).filter(([id])=>!s.activePlayers||s.activePlayers.includes(id)).map(([id,p])=>[id,...round(p)]),pucks:(Array.isArray(s.pucks)?s.pucks:s.puckOnIce===false?[]:[s.puck]).map(round),step:s.turn});
 }
 return {title:record.title||'CourtIQ 演練',fps,duration,frames,lines:record.history.map(s=>s.annotations||[])};
}
// Self-contained: this exact function is embedded into downloadable HTML.
export function paintPortable(canvas,data,time){
 const c=canvas.getContext('2d'),f=data.frames[Math.min(data.frames.length-1,Math.max(0,Math.round(time*data.fps)))];
 c.setTransform(canvas.width/1000,0,0,canvas.height/600,0,0);c.fillStyle='#edf3ee';c.fillRect(0,0,1000,600);
 const path=(x,y,w,h,r)=>{c.beginPath();c.roundRect(x,y,w,h,r);};
 path(40,50,920,500,110);c.fillStyle='#fcfefa';c.fill();c.strokeStyle='#adc6c0';c.lineWidth=3;c.stroke();c.save();c.clip();
 for(const x of [125,500,875]){c.strokeStyle='#d58e84';c.lineWidth=2;c.beginPath();c.moveTo(x,50);c.lineTo(x,550);c.stroke();}
 for(const x of [350,650]){c.strokeStyle='#78a7be';c.lineWidth=5;c.beginPath();c.moveTo(x,50);c.lineTo(x,550);c.stroke();}
 for(const [x,y,r] of [[500,300,65],[230,175,57],[230,425,57],[770,175,57],[770,425,57]]){c.strokeStyle=x===500?'#a5c1c8':'#dba69b';c.lineWidth=2;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.stroke();c.fillStyle='#c58f82';c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.fill();}
 c.restore();c.strokeStyle='#c9867c';c.lineWidth=3;c.strokeRect(90,277,20,46);c.strokeRect(890,277,20,46);
 for(const line of data.lines[f.step]||data.lines.at(-1)||[]){const pts=line.points;if(pts.length<2)continue;c.strokeStyle=line.color==='red'?'#d63c45':'#236cbe';c.lineWidth=2.5;c.lineJoin='round';c.lineCap='round';c.setLineDash(line.type==='pass'?[7,5]:[]);
  for(const offset of line.type==='shot'?[-2.5,2.5]:[0]){c.beginPath();let length=0;for(let i=0;i<pts.length;i++){const p=pts[i],prev=pts[Math.max(0,i-1)],next=pts[Math.min(pts.length-1,i+1)];length+=i?Math.hypot(p.x-prev.x,p.y-prev.y):0;const angle=Math.atan2(next.y-prev.y,next.x-prev.x),o=offset+(line.type==='carry'?Math.sin(length/6)*4:0),x=p.x-Math.sin(angle)*o,y=p.y+Math.cos(angle)*o;if(i)c.lineTo(x,y);else c.moveTo(x,y);}c.stroke();}
  c.setLineDash([]);const b=pts.at(-1),a=pts[Math.max(0,pts.length-2)],angle=Math.atan2(b.y-a.y,b.x-a.x);c.beginPath();for(const sign of [-1,1]){c.moveTo(b.x,b.y);c.lineTo(b.x-12*Math.cos(angle)+sign*6*Math.sin(angle),b.y-12*Math.sin(angle)-sign*6*Math.cos(angle));}c.stroke();
 }
 for(const [id,x,y] of f.players){c.beginPath();c.arc(x,y,13,0,Math.PI*2);c.fillStyle=id.startsWith('O')?'#b56b5c':'#277b76';c.fill();c.strokeStyle='#fff';c.lineWidth=2;c.stroke();c.fillStyle='#fff';c.font='bold 10px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(id,x,y);}
 f.pucks.forEach(([x,y],i)=>{c.beginPath();c.arc(x,y,4,0,Math.PI*2);c.fillStyle='#173638';c.fill();c.fillStyle='#355b56';c.font='9px sans-serif';c.fillText('P'+(i+1),x+12,y);});
 c.fillStyle='#355b56';c.font='13px sans-serif';c.textAlign='left';c.fillText('CourtIQ Ice · 第 '+f.step+' 步',42,25);c.textAlign='right';c.fillText('教學演練 · 非比賽預測',958,580);
}
export function portableHTML(record){const data=JSON.stringify(portableReplay(record)).replace(/</g,'\\u003c');return `<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CourtIQ 演練回放</title><style>body{margin:20px;background:#f7f8f1;color:#183b3e;font:16px system-ui}canvas{width:100%;max-height:78vh;object-fit:contain}button,input{padding:12px;margin:6px}input{width:55%}</style><h2 id="title"></h2><canvas width="1280" height="768"></canvas><div><button id="play">播放</button><button id="restart">回起點</button><input id="seek" type="range" min="0" step=".05"><span id="time"></span></div><p>離線演練回放 · 不需安裝軟體；修改請使用原 JSON 戰術備份。</p><script>const data=${data};const paint=${paintPortable.toString()};const c=document.querySelector('canvas'),seek=document.querySelector('#seek'),play=document.querySelector('#play');document.querySelector('#title').textContent=data.title;seek.max=data.duration;let t=0,running=false,last=0;function draw(){paint(c,data,t);seek.value=t;document.querySelector('#time').textContent=t.toFixed(1)+' / '+data.duration+' 秒';play.textContent=running?'暫停':'播放';}function tick(now){if(running){t=Math.min(data.duration,t+(now-last)/1000);if(t>=data.duration)running=false;draw();}last=now;requestAnimationFrame(tick);}play.onclick=()=>{if(t>=data.duration)t=0;running=!running;draw();};seek.oninput=()=>{running=false;t=Number(seek.value);draw();};document.querySelector('#restart').onclick=()=>{t=0;running=false;draw();};draw();requestAnimationFrame(tick);<\/script></html>`;}
export async function encodeShare(record){if(!globalThis.CompressionStream)throw Error('此瀏覽器無法產生壓縮連結，請匯出 HTML');const bytes=await new Response(new Blob([JSON.stringify(record)]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer();const encoded=btoa(String.fromCharCode(...new Uint8Array(bytes))).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'');if(encoded.length>24000)throw Error('演練超過連結容量，請改用 HTML 或影片');return encoded;}
export async function decodeShare(encoded){if(encoded.length>24000||!/^[-_a-zA-Z0-9]+$/.test(encoded))throw Error('分享連結格式無效');const binary=atob(encoded.replaceAll('-','+').replaceAll('_','/')),stream=new Blob([Uint8Array.from(binary,x=>x.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'));const reader=stream.getReader();let length=0,chunks=[];for(;;){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>150*1024){await reader.cancel();throw Error('分享資料過大');}chunks.push(value);}return JSON.parse(await new Blob(chunks).text());}
export function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
export function mountReplayExports(getSnapshot){
 const dialog=document.createElement('dialog');dialog.className='replay-export-dialog';dialog.innerHTML='<h2>分享與匯出</h2><p>輸出已加入的步驟。PNG 為目前步驟的全場圖；HTML 與影片包含完整演練。</p><div class="export-buttons"><button data-export="png">目前步驟 PNG</button><button data-export="html">離線回放 HTML</button><button data-export="video">匯出演練影片</button><button data-export="link">產生觀看連結</button></div><p>影片優先使用 MP4；瀏覽器不支援時會下載 WebM。錄製期間請留在此分頁。</p><p>分享連結把戰術資料放在網址中，不含影片、不上傳雲端。持有連結者可觀看；目前無法撤回或設定期限，長網址可能被通訊軟體截斷。</p><textarea aria-label="分享連結" readonly hidden></textarea><button data-copy hidden>複製連結</button><p role="status"></p><button data-close>關閉</button>';
 document.body.append(dialog);const status=dialog.querySelector('[role=status]'),buttons=[...dialog.querySelectorAll('[data-export]')];let busy=false,cancel=false;
 const open=document.createElement('button');open.textContent='分享／圖片／影片';open.type='button';document.querySelector('.replay-save').append(open);open.onclick=()=>{status.textContent='';dialog.showModal();};dialog.querySelector('[data-close]').onclick=()=>{if(busy){cancel=true;status.textContent='正在取消錄製…';}else dialog.close();};dialog.addEventListener('cancel',e=>{if(busy){e.preventDefault();cancel=true;}});
 const linkBox=dialog.querySelector('textarea'),copy=dialog.querySelector('[data-copy]');copy.onclick=async()=>{try{await navigator.clipboard.writeText(linkBox.value);status.textContent='已複製觀看連結';}catch{linkBox.select();status.textContent='請手動複製上方連結';}};
 buttons.forEach(b=>b.onclick=async()=>{if(busy)return;busy=true;cancel=false;buttons.forEach(x=>x.disabled=true);try{const {record,frame}=getSnapshot(),data=portableReplay(record),canvas=document.createElement('canvas');canvas.width=1280;canvas.height=768;
  if(b.dataset.export==='html'){download(new Blob([portableHTML(record)],{type:'text/html;charset=utf-8'}),'CourtIQ_Replay.html');status.textContent='已匯出 HTML；使用瀏覽器開啟即可回放';}
  if(b.dataset.export==='png'){const still=portableReplay({...record,history:[frame]});paintPortable(canvas,still,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('無法建立圖片');download(blob,'CourtIQ_Step_'+frame.turn+'.png');status.textContent='已匯出目前步驟 PNG（全場）';}
  if(b.dataset.export==='link'){linkBox.value=new URL('watch.html',location.href).href+'#'+await encodeShare(record);linkBox.hidden=false;copy.hidden=false;status.textContent='觀看連結已產生，請複製分享';}
  if(b.dataset.export==='video'){if(!globalThis.MediaRecorder||!canvas.captureStream)throw Error('此瀏覽器不支援錄製，請匯出 HTML');if(!data.duration)throw Error('請先加入至少一步動作');const mime=['video/mp4;codecs=avc1.42E01E','video/mp4','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('此瀏覽器沒有支援的影片編碼');const stream=canvas.captureStream(30),recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:2500000}),chunks=[];try{const done=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=resolve;recorder.onerror=()=>reject(Error('錄製失敗，請改匯出 HTML'));});paintPortable(canvas,data,0);recorder.start(1000);await new Promise(resolve=>{const start=performance.now();function tick(now){const t=Math.min(data.duration,(now-start)/1000);paintPortable(canvas,data,t);status.textContent='錄製 '+t.toFixed(1)+' / '+data.duration+' 秒';if(cancel||t>=data.duration)return resolve();requestAnimationFrame(tick);}requestAnimationFrame(tick);});recorder.stop();await done;if(cancel)status.textContent='已取消，未輸出影片';else{const mp4=mime.startsWith('video/mp4');download(new Blob(chunks,{type:mime}),'CourtIQ_Replay.'+(mp4?'mp4':'webm'));status.textContent='已匯出 '+(mp4?'MP4':'WebM（此瀏覽器不支援 MP4 錄製）');}}finally{if(recorder.state!=='inactive')recorder.stop();stream.getTracks().forEach(t=>t.stop());}}
 }catch(e){status.textContent=e.message;}finally{busy=false;buttons.forEach(x=>x.disabled=false);}});
 return {open:()=>open.click()};
}
